// DeviceAdminServiceServer is the server API for DeviceAdminService service.
// All implementations should embed UnimplementedDeviceAdminServiceServer
// for forward compatibility.
//
// DeviceAdminService registers, enables/disables and removes devices - the
// privileged operations internal/admin implements (a JSON/HTML UI on port
// 8081 used to expose these too; retired once gateway-web reached parity
// with it, see docs/decisions.md ADR-015). See ADR-013 for why this is
// answered directly by the admin (root) process instead of being proxied
// like DeviceService/GatewayService are.
type DeviceAdminServiceServer interface {
	// RegisterExistingDevice adopts a known broker identity without generating
	// or rotating a password. It is for local services installed separately
	// from the gateway, such as orangepi-monitor.
	RegisterExistingDevice(context.Context, *RegisterExistingDeviceRequest) (*RegisterExistingDeviceResponse, error)
	// Routes belong to the same versioned SQLite policy as devices. They are
	// applied by the live gateway without restarting either systemd service.
	ListRoutes(context.Context, *ListRoutesRequest) (*ListRoutesResponse, error)
	CreateRoute(context.Context, *CreateRouteRequest) (*CreateRouteResponse, error)
	RemoveRoute(context.Context, *RemoveRouteRequest) (*RemoveRouteResponse, error)
	// ListDeviceManifests exposes only published family definitions. Draft
	// editing/publishing is deliberately a later milestone.
	ListDeviceManifests(context.Context, *ListDeviceManifestsRequest) (*ListDeviceManifestsResponse, error)
	GetDeviceManifest(context.Context, *GetDeviceManifestRequest) (*GetDeviceManifestResponse, error)
	ListDeviceManifestBindings(context.Context, *ListDeviceManifestBindingsRequest) (*ListDeviceManifestBindingsResponse, error)
	CreateDeviceManifestDraft(context.Context, *CreateDeviceManifestDraftRequest) (*CreateDeviceManifestDraftResponse, error)
	CreateDeviceManifestRevisionDraft(context.Context, *CreateDeviceManifestRevisionDraftRequest) (*CreateDeviceManifestRevisionDraftResponse, error)
	PublishDeviceManifest(context.Context, *PublishDeviceManifestRequest) (*PublishDeviceManifestResponse, error)
	ProvisionDevice(context.Context, *ProvisionDeviceRequest) (*ProvisionDeviceResponse, error)
	// ProvisionDeviceByIP provisions an unprovisioned device using a published
	// http-nvs-v1 manifest. The MQTT password is delivered directly to NVS and
	// never appears in this API response.
	ProvisionDeviceByIP(context.Context, *ProvisionDeviceByIPRequest) (*ProvisionDeviceByIPResponse, error)
	// ProvisionCYD delivers the MQTT identity to an unprovisioned CYD over its
	// temporary LAN endpoint. Unlike ProvisionDevice, it never returns a
	// password to the caller.
	ProvisionCYD(context.Context, *ProvisionCYDRequest) (*ProvisionCYDResponse, error)
	// ProvisionLED delivers the MQTT identity to an unprovisioned ESP32-C3 LED
	// over its temporary LAN endpoint. The password is never returned to the
	// browser.
	ProvisionLED(context.Context, *ProvisionLEDRequest) (*ProvisionLEDResponse, error)
	SetDeviceEnabled(context.Context, *SetDeviceEnabledRequest) (*SetDeviceEnabledResponse, error)
	RemoveDevice(context.Context, *RemoveDeviceRequest) (*RemoveDeviceResponse, error)
	// ListInconsistencies returns provisioning operations whose best-effort
	// compensation itself failed - the registry and the Mosquitto broker now
	// disagree about a device. Empty is the healthy state. See docs/api-v1.md.
	ListInconsistencies(context.Context, *ListInconsistenciesRequest) (*ListInconsistenciesResponse, error)
	ResolveInconsistency(context.Context, *ResolveInconsistencyRequest) (*ResolveInconsistencyResponse, error)
}

